import{_ as l,o,c as i,a2 as a}from"./chunks/framework.DCrEymYf.js";const g=JSON.parse('{"title":"列表页 UI 规范","description":"","frontmatter":{},"headers":[],"relativePath":"mango-pmo/rules/frontend/08-list-page.md","filePath":"mango-pmo/rules/frontend/08-list-page.md"}'),d={name:"mango-pmo/rules/frontend/08-list-page.md"};function c(n,e,t,r,s,h){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="列表页-ui-规范" tabindex="-1">列表页 UI 规范 <a class="header-anchor" href="#列表页-ui-规范" aria-label="Permalink to &quot;列表页 UI 规范&quot;">​</a></h1><h2 id="_1-页面结构" tabindex="-1">1. 页面结构 <a class="header-anchor" href="#_1-页面结构" aria-label="Permalink to &quot;1. 页面结构&quot;">​</a></h2><ol><li>列表页内容区不展示页面标题、面包屑、页签标题。</li><li>列表页不展示“搜索条件”“数据列表”等卡片标题。</li><li>标准结构为：搜索区、功能区、表格区、分页区。</li><li>搜索区和表格区通过白底、轻阴影、圆角和间距区分。</li><li>新增列表页必须优先使用 <code>@mango/common</code> 的 <code>MangoListPage</code>、<code>MangoSearchPanel</code>、<code>MangoListPanel</code> 和 <code>Pagination</code> 组织骨架。</li><li>禁止在业务页面自定义 <code>.operation-page</code>、<code>.query-form</code>、<code>.table-toolbar</code>、<code>.pagination-wrap</code> 等替代统一骨架的页面结构。</li></ol><h2 id="_2-搜索区" tabindex="-1">2. 搜索区 <a class="header-anchor" href="#_2-搜索区" aria-label="Permalink to &quot;2. 搜索区&quot;">​</a></h2><ol><li>搜索条件使用 <code>MangoSearchPanel</code> 承载，业务只声明 <code>el-form-item</code> 字段，不在页面内重写搜索区布局。</li><li>桌面端搜索项使用稳定字段宽度，不因为只有 1 个筛选项就横向铺满整行；移动端可以单列撑满。</li><li>搜索项多于默认展示范围时必须启用 <code>collapsible</code>，收起态只显示常用搜索项。</li><li>常用搜索项按字段顺序表达，业务把高频条件放在前面；需要精确控制时使用 <code>collapsed-count</code>。</li><li>展开态显示全部搜索项，展开/收起按钮跟随查询、重置按钮区域。</li><li>查询、重置、展开或收起按钮统一位于搜索卡片右下角；展开前后位置必须稳定。</li><li>主按钮顺序固定为查询、重置、展开或收起。</li><li>展开/收起图标使用 Element Plus Icons。</li><li>时间范围使用 range 类型，不拆成两个无关联输入。</li><li>搜索条件变化后分页回到第一页。</li></ol><h2 id="_3-功能区" tabindex="-1">3. 功能区 <a class="header-anchor" href="#_3-功能区" aria-label="Permalink to &quot;3. 功能区&quot;">​</a></h2><ol><li>功能区通过 <code>MangoListPanel</code> 的 <code>actions</code> slot 放业务操作。</li><li>不默认放刷新、列设置、密度切换等工具按钮；确需视图操作时放 <code>view-actions</code> slot。</li><li>功能区按钮统一使用 <code>plain</code> 风格。</li><li>主操作使用 <code>primary plain</code>。</li><li>危险操作使用 <code>danger plain</code>。</li><li>批量操作未选择数据时禁用。</li><li>删除类按钮即使禁用，也保留 <code>danger</code> 语义。</li></ol><h2 id="_4-表格区" tabindex="-1">4. 表格区 <a class="header-anchor" href="#_4-表格区" aria-label="Permalink to &quot;4. 表格区&quot;">​</a></h2><ol><li>表格使用 <code>ElTable</code> 或项目统一表格组件。</li><li>表格列宽、状态、操作列和分页保持稳定。</li><li>操作列固定右侧。</li><li>行内操作使用文本按钮。</li><li>行内删除使用 <code>danger</code> 文本样式。</li><li>空值统一显示 <code>-</code>。</li><li>状态统一使用 <code>ElTag</code> 或公共状态组件。</li><li>分页位于表格下方，分页数据由接口结果驱动。</li></ol><h2 id="_5-检查清单" tabindex="-1">5. 检查清单 <a class="header-anchor" href="#_5-检查清单" aria-label="Permalink to &quot;5. 检查清单&quot;">​</a></h2><ol><li>是否误放页面标题、面包屑或卡片标题。</li><li>是否使用 <code>MangoListPage</code>、<code>MangoSearchPanel</code>、<code>MangoListPanel</code> 和 <code>Pagination</code>。</li><li>搜索项较多时是否按常用项在前并启用展开/收起。</li><li>查询、重置、展开或收起按钮是否在搜索卡片右下角且展开前后稳定。</li><li>单筛选项是否保持合理宽度，未横向铺满整行。</li><li>功能区按钮是否统一 <code>plain</code>。</li><li>删除、批量删除是否使用 <code>danger</code>。</li><li>表格操作列、状态列、分页是否稳定。</li><li>是否覆盖 loading、empty、error 和无权限状态。</li></ol>',11)])])}const m=l(d,[["render",c]]);export{g as __pageData,m as default};
